module file_deletion (\n    input clk,\n    input rst_n,\n    input start,\n    input [13:0] nr, nc,\n    input [2:0] N,\n    input [231:0] points_packed,\n    output reg [3:0] moves,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] LOAD    = 3'd1;\n    localparam [2:0] SORT    = 3'd2;\n    localparam [2:0] ITERATE = 3'd3;\n    localparam [2:0] COMPUTE = 3'd4;\n    localparam [2:0] FINISH  = 3'd5;\n    \n    reg [2:0] state, next_state;\n    \n    // Data storage\n    reg [13:0] x_coords [0:7];\n    reg [13:0] y_coords [0:7];\n    reg types [0:7];\n    reg [3:0] n_delete;\n\n    // Coordinate arrays\n    reg [13:0] xs [0:9];\n    reg [13:0] ys [0:9];\n    reg [3:0] xs_count;\n    reg [3:0] ys_count;\n\n    // Iteration indices\n    reg [3:0] x_left, x_right;\n    reg [3:0] y_low, y_high;\n    reg [3:0] i;\n    \n    // Algorithm registers\n    reg [3:0] max_f;\n    reg [3:0] current_f;\n    reg [3:0] sort_idx;\n    \n    // Point unpacking\n    wire [28:0] point [0:7];\n    generate\n        genvar k;\n        for (k=0; k<8; k=k+1) begin : unpack\n            assign point[k] = points_packed[29*k +: 29];\n        end\n    endgenerate\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) state <= IDLE;\n        else state <= next_state;\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE:    if (start) next_state = LOAD;\n            LOAD:    next_state = SORT;\n            SORT:    if (sort_idx == 4'd8) next_state = ITERATE;\n            ITERATE: if (x_left < xs_count-1) next_state = COMPUTE;\n                     else next_state = FINISH;\n            COMPUTE: if (y_high < ys_count) next_state = ITERATE;\n                     else if (x_right < xs_count-1) next_state = ITERATE;\n                     else if (x_left < xs_count-2) next_state = ITERATE;\n                     else next_state = FINISH;\n            FINISH:  next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Main processing\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            done <= 1'b0;\n            moves <= 4'd0;\n            max_f <= 4'd0;\n            current_f <= 4'd0;\n            sort_idx <= 4'd0;\n            x_left <= 4'd0;\n            x_right <= 4'd1;\n            y_low <= 4'd0;\n            y_high <= 4'd1;\n            xs_count <= 4'd2;\n            ys_count <= 4'd2;\n            n_delete <= 4'd0;\n            xs[0] <= 14'd0;\n            xs[1] <= nr;\n            ys[0] <= 14'd0;\n            ys[1] <= nc;\n            for (integer idx=0; idx<8; idx=idx+1) begin\n                x_coords[idx] <= 14'd0;\n                y_coords[idx] <= 14'd0;\n                types[idx] <= 1'b0;\n            end\n            for (integer jdx=2; jdx<10; jdx=jdx+1) begin\n                xs[jdx] <= 14'd0;\n                ys[jdx] <= 14'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Initialize coordinates\n                        xs[0] <= 14'd0;\n                        xs[1] <= nr;\n                        ys[0] <= 14'd0;\n                        ys[1] <= nc;\n                        xs_count <= 4'd2;\n                        ys_count <= 4'd2;\n                        n_delete <= 4'd0;\n                    end\n                end\n                \n                LOAD: begin\n                    for (integer idx=0; idx<8; idx=idx+1) begin\n                        if (idx < N) begin\n                            types[idx] <= point[idx][28];\n                            x_coords[idx] <= point[idx][27:14];\n                            y_coords[idx] <= point[idx][13:0];\n                            if (point[idx][28]) n_delete <= n_delete + 1;\n                        end\n                    end\n                end\n                \n                SORT: begin\n                    if (sort_idx < N) begin\n                        // Store x coordinate if new\n                        if (x_coords[sort_idx] != xs[0] && x_coords[sort_idx] != xs[1]) begin\n                            xs[xs_count] <= x_coords[sort_idx];\n                            xs_count <= xs_count + 1;\n                        end\n                        // Store y coordinate if new\n                        if (y_coords[sort_idx] != ys[0] && y_coords[sort_idx] != ys[1]) begin\n                            ys[ys_count] <= y_coords[sort_idx];\n                            ys_count <= ys_count + 1;\n                        end\n                        sort_idx <= sort_idx + 1;\n                    end\n                end\n                \n                ITERATE: begin\n                    // Reset current_f for new rectangle\n                    current_f <= 4'd0;\n                    // Iterate through all points\n                    i <= 4'd0;\n                end\n                \n                COMPUTE: begin\n                    if (i < N) begin\n                        if (x_coords[i] >= xs[x_left] && x_coords[i] <= xs[x_right] &&\n                            y_coords[i] >= ys[y_low] && y_coords[i] <= ys[y_high]) begin\n                            current_f <= types[i] ? current_f + 1 : current_f - 1;\n                        end\n                        i <= i + 1;\n                    end else begin\n                        // Update max_f\n                        if (current_f > max_f) max_f <= current_f;\n                        // Update indices\n                        if (y_high < ys_count - 1) begin\n                            y_high <= y_high + 1;\n                        end else if (x_right < xs_count - 1) begin\n                            y_high <= 4'd1;\n                            x_right <= x_right + 1;\n                        end else begin\n                            y_high <= 4'd1;\n                            x_right <= x_left + 2;\n                            x_left <= x_left + 1;\n                        end\n                    end\n                end\n                \n                FINISH: begin\n                    moves <= n_delete - max_f;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\nendmodule